//! NIST SP 800-38D (caso de teste 16 de `McGrew` e `Viega`, AES-256) e casos
//! diferenciais contra o OpenSSL (pacote `cryptography` do Python). Os
//! testes só rodam se a CPU tem AES-NI e PCLMULQDQ.

use super::*;
use crate::testutil::hex;

fn de_hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn chave(s: &str) -> Secret<32> {
    Secret::take(&mut de_hex(s).try_into().unwrap())
}

#[test]
fn nist_caso_16() {
    if !available() {
        return;
    }
    let k = chave("feffe9928665731c6d6a8f9467308308feffe9928665731c6d6a8f9467308308");
    let n: [u8; 12] = de_hex("cafebabefacedbaddecaf888").try_into().unwrap();
    let aad = de_hex("feedfacedeadbeeffeedfacedeadbeefabaddad2");
    let mut buf = de_hex(
        "d9313225f88406e5a55909c5aff5269a86a7a9531534f7da2e4c303d8a318a721c3c0c95956809532fcf0e2449a6b525b16aedf5aa0de657ba637b39",
    );
    let g = AesGcm::new(&k).unwrap();
    let tag = g.seal(&n, &aad, &mut buf);
    assert_eq!(
        hex(&buf),
        "522dc1f099567d07f47f37a32a84427d643a8cdcbfe5c0c97598a2bd2555d1aa8cb08e48590dbb3da7b08b1056828838c5f61e6393ba7a0abcc9f662"
    );
    assert_eq!(hex(&tag), "76fc6ece0f4e1768cddf8853bb2d551b");
}

