#[test]
fn diferencial_e_ida_e_volta() {
    if !available() {
        return;
    }
    for (k, n, a, p, c, t) in CASOS {
        let g = AesGcm::new(&chave(k)).unwrap();
        let (aad, nonce): (_, [u8; 12]) = (de_hex(a), de_hex(n).try_into().unwrap());
        let mut buf = de_hex(p);
        let tag = g.seal(&nonce, &aad, &mut buf);
        assert_eq!((hex(&buf), hex(&tag)), (c.to_string(), t.to_string()));
        g.open(&nonce, &aad, &mut buf, &tag).unwrap();
        assert_eq!(hex(&buf), *p);
    }
}

/// P6: tag, texto cifrado ou AAD adulterados recusam e zeram o buffer.
#[test]
fn adulteracao_recusada_e_buffer_zerado() {
    if !available() {
        return;
    }
    let g = AesGcm::new(&chave(&"42".repeat(32))).unwrap();
    let (nonce, aad) = ([5u8; 12], *b"cabecalho");
    let mut ct = [0x33u8; 40];
    let tag = g.seal(&nonce, &aad, &mut ct);
    for i in 0..TAG_LEN {
        let mut ruim = tag;
        ruim[i] ^= 1;
        let mut b = ct;
        assert_eq!(g.open(&nonce, &aad, &mut b, &ruim), Err(AuthError));
        assert_eq!(b, [0; 40]);
    }
    for i in 0..ct.len() {
        let mut b = ct;
        b[i] ^= 1;
        assert_eq!(g.open(&nonce, &aad, &mut b, &tag), Err(AuthError));
        assert_eq!(b, [0; 40]);
    }
    let mut b = ct;
    assert_eq!(g.open(&nonce, b"cabecalhx", &mut b, &tag), Err(AuthError));
}
